import json
P = "models/"
def R(cid, obj, sense, solver, summary, ia=False, rel=None, issue="NONE", note="", readings=None, conf="HIGH",
      ptype=None, tal=None, trat="", tconf=None, notes="", status="Optimal", asked=None):
    return dict(case_id=cid, status=status, objective=obj, sense=sense, model_file=P+cid+".py", output_file=P+cid+".out.txt",
                solver=solver, model_summary=summary, integrality_ambiguous=ia, integer_relaxed_objective=rel, asked_value=asked,
                issue=issue, issue_note=note, readings=readings or [], confidence=conf, problem_type=ptype,
                type_after_linearization=tal, type_rationale=trat, type_confidence=tconf, notes=notes)
def rd(text, obj, f, st="Optimal"): return dict(reading=text, objective=obj, status=st, model_file=P+f)
